import {heading} from './shared.js';
const projects=[{name:'essenza',label:'SAÚDE & BEM-ESTAR',title:'Cuidado que começa<br>no primeiro contato.',copy:'Uma presença acolhedora para clínicas e profissionais de saúde. Serviços organizados e agendamento sempre por perto.',screen:'O cuidado que você merece.',sub:'Um novo olhar para o seu bem-estar.',tone:'clinic',items:['Clínica / médico','Estética'],stats:['Cuidado integral','Atendimento humanizado','Agende sua consulta']},{name:'forno & fogo',label:'GASTRONOMIA & COMÉRCIO',title:'Uma experiência boa<br>antes da primeira visita.',copy:'Apresente seu cardápio, destaque seus produtos e facilite os pedidos. O sabor do seu negócio também pode estar no digital.',screen:'Feito com tempo.<br>Servido com alma.',sub:'Da nossa cozinha para a sua melhor noite.',tone:'food',items:['Restaurante','Comércio local'],stats:['Ingredientes selecionados','Nossa história','Faça seu pedido']},{name:'VÉRTICE',label:'SERVIÇOS & NEGÓCIOS',title:'Confiança para quem<br>precisa do seu serviço.',copy:'Uma apresentação clara dos seus diferenciais, com informações acessíveis e um caminho simples para entrar em contato.',screen:'Clareza para decidir.<br>Confiança para seguir.',sub:'Soluções construídas para o seu momento.',tone:'legal',items:['Advogado','Prestador de serviços'],stats:['Atuação estratégica','Conheça nossa equipe','Fale com um especialista']}];
const screen=(p)=>`<div class="demo-site ${p.tone}"><div class="demo-nav"><strong>${p.name}</strong><span>Sobre &nbsp; Serviços &nbsp; Contato</span></div><div class="demo-body"><span class="demo-kicker">${p.label}</span><h4>${p.screen}</h4><p>${p.sub}</p><span class="demo-button">${p.stats[2]} ↗</span></div><div class="demo-foot"><span>${p.stats[0]}</span><span>${p.stats[1]}</span></div></div>`;
export const portfolio=()=>`<section class="section container" id="projetos">${heading('POSSIBILIDADES PARA A SUA MARCA','Veja o que podemos<br>criar para você','Cada negócio tem uma história. O seu site deve contar a sua.')}<div class="project-list">${projects.map((p,i)=>`<article class="project-row reveal"><div class="project-preview"><div class="browser-bar"><span>● ● ●</span><span>${p.name} · conceito de interface</span><span>↗</span></div>${screen(p)}</div><div class="project-copy"><span class="eyebrow">0${i+1} / ${p.label}</span><h3>${p.title}</h3><p>${p.copy}</p><div class="tags">${p.items.map(x=>`<span>${x}</span>`).join('')}</div><a class="text-link" href="#contato">Quero um site assim ↗</a></div></article>`).join('')}</div><p class="demo-notice">Projetos conceituais desenvolvidos para ilustrar possibilidades de design.</p></section>`;
